package main
import("fmt";"time";"github.com/gofiber/fiber/v2")
type Lab struct{ID string `json:"id"`;Slug string `json:"slug"`;Title string `json:"title"`;Description string `json:"description"`;Status string `json:"status"`;Endpoint string `json:"endpoint"`;CreatedAt time.Time `json:"createdAt"`;UpdatedAt time.Time `json:"updatedAt"`}
var labs=map[string]Lab{}
func main(){app:=fiber.New();seed();find:=func(id string)(Lab,bool){for _,x:=range labs{if x.ID==id||x.Slug==id{return x,true}};return Lab{},false};app.Get("/labs",func(c *fiber.Ctx)error{out:=[]Lab{};for _,x:=range labs{out=append(out,x)};return c.JSON(out)});app.Get("/labs/:id",func(c *fiber.Ctx)error{x,ok:=find(c.Params("id"));if !ok{return c.SendStatus(404)};return c.JSON(x)});app.Post("/labs",func(c *fiber.Ctx)error{var in struct{Slug string `json:"slug"`;Title string `json:"title"`;Description string `json:"description"`;Status string `json:"status"`};if err:=c.BodyParser(&in);err!=nil{return c.Status(400).JSON(fiber.Map{"error":err.Error()})};now:=time.Now();id:=fmt.Sprintf("fiber-%d",now.UnixNano());x:=Lab{id,in.Slug,in.Title,in.Description,in.Status,"/labs/"+in.Slug,now,now};labs[x.ID]=x;return c.Status(201).JSON(x)});update:=func(c *fiber.Ctx)error{x,ok:=find(c.Params("id"));if !ok{return c.SendStatus(404)};var in map[string]string;c.BodyParser(&in);if v:=in["title"];v!=""{x.Title=v};if v:=in["status"];v!=""{x.Status=v};x.UpdatedAt=time.Now();labs[x.ID]=x;return c.JSON(x)};app.Put("/labs/:id",update);app.Patch("/labs/:id",update);app.Delete("/labs/:id",func(c *fiber.Ctx)error{x,ok:=find(c.Params("id"));if !ok{return c.SendStatus(404)};delete(labs,x.ID);return c.JSON(fiber.Map{"deleted":true,"id":x.ID})});app.Listen(":4009")}
func seed(){now:=time.Now();labs["fiber"]=Lab{"fiber","fiber","Go Fiber CRUD","Go Fiber CRUD lab.","ready","/labs/fiber",now,now}}
